        for (int i = 0; i < rows; ++i) {
            if (i != 0 && i != rows - 1) {
                System.out.print(String.format("%1$" + padLength + "s", i));
            } else {
                System.out.print(StringUtils.createPadding(padLength, ' '));
            }

            Arrays.stream(cells[i]).forEachOrdered(elem -> System.out.print(elem.toSingleChar()));

            if (i != 0 && i != rows - 1) {
                System.out.print(i);
            }

            System.out.println();
        }

        printColumns.run();
    }

    public void undo(final Coordinate coord) {
        if (coord.row < 0 || coord.row >= rows || coord.col < 0 || coord.col >= cols) {
            throw new IllegalArgumentException("Coordinate out of bounds");
        }

        Cell cell = cells[coord.row][coord.col];
        if (!(cell instanceof FillableCell)) {
            throw new IllegalArgumentException("Cannot undo non-fillable cell");
        }

        ((FillableCell) cell).setPipe(null);
    }

    public void fillBeginTile() {
        sourceCell.setFilled();
    }

    public void fillTiles(int distance) {
        if (prevFilledDistance != null && distance <= prevFilledDistance) {
            return;
        }

        prevFilledDistance = distance;
        prevFilledTiles = filledTiles.size();

        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        filledTiles.add(sourceCell.coord);

        while (!queue.isEmpty() && distance >= 0) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Coordinate current = queue.poll();
                Cell cell = cells[current.row][current.col];

                if (cell instanceof TerminationCell) {
                    TerminationCell tc = (TerminationCell) cell;
                    if (tc.isFilled) {
                        Direction dir = tc.pointingTo;
                        Coordinate next = current.add(dir.getOffset());
                        if (isValidCoordinate(next) && !filledTiles.contains(next)) {
                            Cell nextCell = cells[next.row][next.col];
                            if (nextCell instanceof FillableCell) {
                                FillableCell fc = (FillableCell) nextCell;
                                if (fc.getPipe().isPresent()) {
                                    Pipe pipe = fc.getPipe().get();
                                    if (Arrays.asList(pipe.getConnections()).contains(dir.getOpposite())) {
                                        fc.setFilled();
                                        filledTiles.add(next);
                                        queue.add(next);
                                    }
                                }
                            }
                        }
                    }
                } else if (cell instanceof FillableCell) {
                    FillableCell fc = (FillableCell) cell;
                    if (fc.getPipe().isPresent() && fc.getPipe().get().getFilled()) {
                        for (Direction dir : fc.getPipe().get().getConnections()) {
                            Coordinate next = current.add(dir.getOffset());
                            if (isValidCoordinate(next) && !filledTiles.contains(next)) {
                                Cell nextCell = cells[next.row][next.col];
                                if (nextCell instanceof FillableCell) {
                                    FillableCell nextFc = (FillableCell) nextCell;
                                    if (nextFc.getPipe().isPresent()) {
                                        Pipe nextPipe = nextFc.getPipe().get();
                                        if (Arrays.asList(nextPipe.getConnections()).contains(dir.getOpposite())) {
                                            nextFc.setFilled();
                                            filledTiles.add(next);
                                            queue.add(next);
                                        }
                                    }
                                } else if (nextCell instanceof TerminationCell) {
                                    TerminationCell tc = (TerminationCell) nextCell;
                                    if (tc.pointingTo.getOpposite() == dir) {
                                        tc.setFilled();
                                        filledTiles.add(next);
                                        queue.add(next);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            distance--;
        }
    }

    public boolean checkPath() {
        Set<Coordinate> visited = new HashSet<>();
        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        visited.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            if (current.equals(sinkCell.coord)) {
                return true;
            }

            Cell cell = cells[current.row][current.col];
            if (cell instanceof TerminationCell) {
                TerminationCell tc = (TerminationCell) cell;
                if (tc.isFilled) {
                    Direction dir = tc.pointingTo;
                    Coordinate next = current.add(dir.getOffset());
                    if (isValidCoordinate(next) && !visited.contains(next)) {
                        visited.add(next);
                        queue.add(next);
                    }
                }
            } else if (cell instanceof FillableCell) {
                FillableCell fc = (FillableCell) cell;
                if (fc.getPipe().isPresent() && fc.getPipe().get().getFilled()) {
                    for (Direction dir : fc.getPipe().get().getConnections()) {
                        Coordinate next = current.add(dir.getOffset());
                        if (isValidCoordinate(next) && !visited.contains(next)) {
                            Cell nextCell = cells[next.row][next.col];
                            if (nextCell instanceof FillableCell) {
                                FillableCell nextFc = (FillableCell) nextCell;
                                if (nextFc.getPipe().isPresent()) {
                                    Pipe nextPipe = nextFc.getPipe().get();
                                    if (Arrays.asList(nextPipe.getConnections()).contains(dir.getOpposite())) {
                                        visited.add(next);
                                        queue.add(next);
                                    }
                                }
                            } else if (nextCell instanceof TerminationCell) {
                                TerminationCell tc = (TerminationCell) nextCell;
                                if (tc.pointingTo.getOpposite() == dir) {
                                    visited.add(next);
                                    queue.add(next);
                                }
                            }
                        }
                    }
                }
            }
        }

        return false;
    }

    public boolean hasLost() {
        return prevFilledDistance != null && filledTiles.size() == prevFilledTiles;
    }

    private boolean isValidCoordinate(Coordinate coord) {
        return coord.row >= 0 && coord.row < rows && coord.col >= 0 && coord.col < cols;
    }
}
