```java
package game.map;

import game.map.cells.Cell;
import game.map.cells.FillableCell;
import game.map.cells.TerminationCell;
import game.map.cells.Wall;
import game.pipes.Pipe;
import io.Deserializer;
import util.Coordinate;
import util.Direction;
import util.StringUtils;

import java.io.*;
import java.util.*;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.stream.Stream;

/**
 * Map of the game.
 */
public class Map {

    private final int rows;
    private final int cols;
    public final Cell[][] cells;

    private TerminationCell sourceCell;
    private TerminationCell sinkCell;

    private final Set<Coordinate> filledTiles = new HashSet<>();
    private int prevFilledTiles = 0;
    private Integer prevFilledDistance;

    public Map(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new Cell[rows][cols];

        // Initialize all cells as FillableCells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                cells[i][j] = new FillableCell(new Coordinate(i, j));
            }
        }

        // Place walls around the edges
        for (int i = 0; i < rows; i++) {
            cells[i][0] = new Wall(new Coordinate(i, 0));
            cells[i][cols - 1] = new Wall(new Coordinate(i, cols - 1));
        }
        for (int j = 0; j < cols; j++) {
            cells[0][j] = new Wall(new Coordinate(0, j));
            cells[rows - 1][j] = new Wall(new Coordinate(rows - 1, j));
        }

        // Place source and sink cells
        Random random = new Random();
        // Source must be in non-edge cell
        int sourceRow = 1 + random.nextInt(rows - 2);
        int sourceCol = 1 + random.nextInt(cols - 2);
        Direction sourceDir = Direction.values()[random.nextInt(Direction.values().length)];
        sourceCell = new TerminationCell(new Coordinate(sourceRow, sourceCol), sourceDir, TerminationCell.Type.SOURCE);
        cells[sourceRow][sourceCol] = sourceCell;

        // Sink must be on edge cell
        int sinkRow, sinkCol;
        Direction sinkDir;
        do {
            if (random.nextBoolean()) {
                // Place on top or bottom edge
                sinkRow = random.nextBoolean() ? 0 : rows - 1;
                sinkCol = 1 + random.nextInt(cols - 2);
                sinkDir = sinkRow == 0 ? Direction.UP : Direction.DOWN;
            } else {
                // Place on left or right edge
                sinkRow = 1 + random.nextInt(rows - 2);
                sinkCol = random.nextBoolean() ? 0 : cols - 1;
                sinkDir = sinkCol == 0 ? Direction.LEFT : Direction.RIGHT;
            }
        } while (sinkRow == sourceRow && sinkCol == sourceCol); // Ensure sink is not on same cell as source

        sinkCell = new TerminationCell(new Coordinate(sinkRow, sinkCol), sinkDir, TerminationCell.Type.SINK);
        cells[sinkRow][sinkCol] = sinkCell;
    }

    public Map(int rows, int cols, Cell[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;

        // Find source and sink cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (cells[i][j] instanceof TerminationCell) {
                    TerminationCell tc = (TerminationCell) cells[i][j];
                    if (tc.type == TerminationCell.Type.SOURCE) {
                        sourceCell = tc;
                    } else if (tc.type == TerminationCell.Type.SINK) {
                        sinkCell = tc;
                    }
                }
            }
        }

        // Validate map
        if (sourceCell == null || sinkCell == null) {
            throw new IllegalArgumentException("Map must contain exactly one source and one sink cell");
        }
    }

    static Map fromString(int rows, int cols, String cellsRep) {
        Cell[][] cells = Deserializer.parseString(rows, cols, cellsRep);
        return new Map(rows, cols, cells);
    }

    public boolean tryPlacePipe(final Coordinate coord, final Pipe pipe) {
        return tryPlacePipe(coord.row, coord.col, pipe);
    }

    boolean tryPlacePipe(int row, int col, Pipe p) {
        if (row < 0 || row >= rows || col < 0 || col >= cols) {
            return false;
        }

        Cell cell = cells[row][col];
        if (!(cell instanceof FillableCell)) {
            return false;
        }

        FillableCell fillableCell = (FillableCell) cell;
        if (fillableCell.getPipe().isPresent()) {
            return false;
        }

        fillableCell.setPipe(p);
        return true;
    }

    public void display() {
        final int padLength = Integer.valueOf(rows - 1).toString().length();

        Runnable printColumns = () -> {
            System.out.print(StringUtils.createPadding(padLength, ' '));
            System.out.print(' ');
            for (int i = 0; i < cols - 2; ++i) {
                System.out.print((char) ('A' + i));
            }
            System.out.println();
        };

        printColumns.run();

        for (int i = 0; i < rows; ++i) {
            if (i != 0 && i != rows - 1) {
                System.out.print(String.format("%1$" + padLength + "s", i));
            } else {
                System.out.print(StringUtils.createPadding(padLength, ' '));
            }

            Arrays.stream(cells[i]).forEachOrdered(elem -> System.out.print(elem.toSingleChar()));

            if (i != 0 && i != rows - 1) {
                System.out.print(i);
            }

            System.out.println();
        }

        printColumns.run();
    }

    public void undo(final Coordinate coord) {
        if (coord.row < 0 || coord.row >= rows || coord.col < 0 || coord.col >= cols) {
            throw new IllegalArgumentException("Coordinate out of bounds");
        }

        Cell cell = cells[coord.row][coord.col];
        if (!(cell instanceof FillableCell)) {
            throw new IllegalArgumentException("Cannot undo non-fillable cell");
        }

        FillableCell fillableCell = (FillableCell) cell;
        fillableCell.setPipe(null);
    }

    public void fillBeginTile() {
        sourceCell.setFilled();
    }

    public void fillTiles(int distance) {
        if (prevFilledDistance != null && distance <= prevFilledDistance) {
            return;
        }

        prevFilledDistance = distance;
        prevFilledTiles = filledTiles.size();

        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        filledTiles.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            Cell cell = cells[current.row][current.col];

            if (cell instanceof FillableCell) {
                FillableCell fillableCell = (FillableCell) cell;
                fillableCell.getPipe().ifPresent(pipe -> {
                    pipe.setFilled();
                    for (Direction dir : pipe.getConnections()) {
                        Coordinate neighbor = current.add(dir.getOffset());
                        if (isValidCoordinate(neighbor) && !filledTiles.contains(neighbor)) {
                            filledTiles.add(neighbor);
                            queue.add(neighbor);
                        }
                    }
                });
            } else if (cell instanceof TerminationCell) {
                TerminationCell terminationCell = (TerminationCell) cell;
                if (terminationCell.type == TerminationCell.Type.SOURCE || terminationCell.isFilled) {
                    Direction dir = terminationCell.pointingTo;
                    Coordinate neighbor = current.add(dir.getOffset());
                    if (isValidCoordinate(neighbor) && !filledTiles.contains(neighbor)) {
                        filledTiles.add(neighbor);
                        queue.add(neighbor);
                    }
                }
            }
        }
    }

    public boolean checkPath() {
        Set<Coordinate> visited = new HashSet<>();
        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        visited.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            Cell cell = cells[current.row][current.col];

            if (cell == sinkCell && ((TerminationCell) cell).isFilled) {
                return true;
            }

            if (cell instanceof FillableCell) {
                FillableCell fillableCell = (FillableCell) cell;
                fillableCell.getPipe().ifPresent(pipe -> {
                    if (pipe.getFilled()) {
                        for (Direction dir : pipe.getConnections()) {
                            Coordinate neighbor = current.add(dir.getOffset());
                            if (isValidCoordinate(neighbor) && !visited.contains(neighbor)) {
                                visited.add(neighbor);
                                queue.add(neighbor);
                            }
                        }
                    }
                });
            } else if (cell instanceof TerminationCell) {
                TerminationCell terminationCell = (TerminationCell) cell;
                if (terminationCell.isFilled) {
                    Direction dir = terminationCell.pointingTo;
                    Coordinate neighbor = current.add(dir.getOffset());
                    if (isValidCoordinate(neighbor) && !visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.add(neighbor);
                    }
                }
            }
        }

        return false;
    }

    public boolean hasLost() {
        return prevFilledDistance != null && filledTiles.size() == prevFilledTiles;
    }

    private boolean isValidCoordinate(Coordinate coord) {
        return coord.row >= 0 && coord.row < rows && coord.col >= 0 && coord.col < cols;
    }
}
