        this.filled = true;
    }

    public boolean getFilled() {
        return filled;
    }

    public Direction[] getConnections() {
        return shape.getConnections();
    }

    @Override
    public char toSingleChar() {
        return shape.getCharByState(filled);
    }

    public static Pipe fromString(String rep) {
        if (rep.length() != 1) {
            throw new IllegalArgumentException("Pipe representation must be a single character");
        }
        char c = rep.charAt(0);
        for (Shape shape : Shape.values()) {
            if (shape.filledChar == c || shape.unfilledChar == c) {
                Pipe pipe = new Pipe(shape);
                if (shape.filledChar == c) {
                    pipe.setFilled();
                }
                return pipe;
            }
        }
        throw new IllegalArgumentException("Invalid pipe character: " + c);
    }

    public enum Shape {
        HORIZONTAL(PipePatterns.Filled.HORIZONTAL, PipePatterns.Unfilled.HORIZONTAL, new Direction[]{Direction.LEFT, Direction.RIGHT}),
        VERTICAL(PipePatterns.Filled.VERTICAL, PipePatterns.Unfilled.VERTICAL, new Direction[]{Direction.UP, Direction.DOWN}),
