        return filled;
    }

    public Direction[] getConnections() {
        return shape.getConnections();
    }

    @Override
    public char toSingleChar() {
        return shape.getCharByState(filled);
    }

    public static Pipe fromString(String rep) {
        if (rep.length() != 1) {
            throw new IllegalArgumentException("Pipe representation must be a single character");
        }
        char c = rep.charAt(0);
        for (Shape shape : Shape.values()) {
            if (shape.filledChar == c || shape.unfilledChar == c) {
                Pipe pipe = new Pipe(shape);
                if (shape.filledChar == c) {
                    pipe.setFilled();
                }
                return pipe;
            }
        }
        throw new IllegalArgumentException("Unknown pipe character: " + c);
    }

    public enum Shape {
        HORIZONTAL(PipePatterns.Filled.HORIZONTAL, PipePatterns.Unfilled.HORIZONTAL, new Direction[]{Direction.LEFT, Direction.RIGHT}),
        VERTICAL(PipePatterns.Filled.VERTICAL, PipePatterns.Unfilled.VERTICAL, new Direction[]{Direction.UP, Direction.DOWN}),
        TOP_LEFT(PipePatterns.Filled.TOP_LEFT, PipePatterns.Unfilled.TOP_LEFT, new Direction[]{Direction.RIGHT, Direction.DOWN}),
        TOP_RIGHT(PipePatterns.Filled.TOP_RIGHT, PipePatterns.Unfilled.TOP_RIGHT, new Direction[]{Direction.LEFT, Direction.DOWN}),
        BOTTOM_LEFT(PipePatterns.Filled.BOTTOM_LEFT, PipePatterns.Unfilled.BOTTOM_LEFT, new Direction[]{Direction.RIGHT, Direction.UP}),
        BOTTOM_RIGHT(PipePatterns.Filled.BOTTOM_RIGHT, PipePatterns.Unfilled.BOTTOM_RIGHT, new Direction[]{Direction.LEFT, Direction.UP}),
        CROSS(PipePatterns.Filled.CROSS, PipePatterns.Unfilled.CROSS, new Direction[]{Direction.UP, Direction.DOWN, Direction.LEFT, Direction.RIGHT});

        final char filledChar;
        final char unfilledChar;
        final Direction[] connections;

        Shape(char filled, char unfilled, Direction[] connections) {
            this.filledChar = filled;
            this.unfilledChar = unfilled;
            this.connections = connections;
        }

        char getCharByState(boolean isFilled) {
            return isFilled ? filledChar : unfilledChar;
        }

        Direction[] getConnections() {
            return connections;
        }
    }
}
